## `lib/serviceInfra.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ServiceInfraArgs {
  environment: string;
  serviceName: string;
  bucketVersioning: boolean;
  bucketEncryption: string;
  rdsInstanceClass: string;
  rdsMultiAZ: boolean;
  rdsBackupRetentionDays: number;
  rdsStorageSize: number;
  enableDeletionProtection: boolean;
  tags: Record<string, string>;
}

export class ServiceInfra extends pulumi.ComponentResource {
  public s3Bucket: aws.s3.Bucket;
  public s3BucketVersioning: aws.s3.BucketVersioningV2;
  public s3BucketServerSideEncryptionConfiguration: aws.s3.BucketServerSideEncryptionConfigurationV2;
  public s3BucketPublicAccessBlock: aws.s3.BucketPublicAccessBlock;
  public rdsInstance: aws.rds.Instance;
  public iamRole: aws.iam.Role;
  public rdsSecurityGroup: aws.ec2.SecurityGroup;

  constructor(
    name: string,
    args: ServiceInfraArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("custom:service:ServiceInfra", name, {}, opts);

    const resourceName = `${args.serviceName}`;
    const componentOpts: pulumi.ResourceOptions = {
      parent: this,
    };

    // ============================================================================
    // S3 Bucket with Versioning and Encryption
    // ============================================================================

    this.s3Bucket = new aws.s3.Bucket(
      `${resourceName}-bucket`,
      {
        tags: args.tags,
      },
      componentOpts
    );

    // Enable versioning
    this.s3BucketVersioning = new aws.s3.BucketVersioningV2(
      `${resourceName}-versioning`,
      {
        bucket: this.s3Bucket.id,
        versioningConfiguration: {
          status: args.bucketVersioning ? "Enabled" : "Suspended",
        },
      },
      componentOpts
    );

    // Server-side encryption (AES-256)
    this.s3BucketServerSideEncryptionConfiguration =
      new aws.s3.BucketServerSideEncryptionConfigurationV2(
        `${resourceName}-encryption`,
        {
          bucket: this.s3Bucket.id,
          rules: [
            {
              applyServerSideEncryptionByDefault: {
                sseAlgorithm: args.bucketEncryption || "AES256",
              },
            },
          ],
        },
        componentOpts
      );

    // Block all public access
    this.s3BucketPublicAccessBlock = new aws.s3.BucketPublicAccessBlock(
      `${resourceName}-public-access-block`,
      {
        bucket: this.s3Bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      componentOpts
    );

    // ============================================================================
    // IAM Role for Service Accounts
    // ============================================================================

    const assumeRolePolicy = JSON.stringify({
      Version: "2012-10-17",
      Statement: [
        {
          Action: "sts:AssumeRole",
          Effect: "Allow",
          Principal: {
            Service: "ec2.amazonaws.com",
          },
        },
      ],
    });

    this.iamRole = new aws.iam.Role(
      `${resourceName}-service-role`,
      {
        assumeRolePolicy,
        tags: args.tags,
      },
      componentOpts
    );

    // IAM policy for S3 bucket access (least-privilege)
    const s3Policy = new aws.iam.RolePolicy(
      `${resourceName}-s3-policy`,
      {
        role: this.iamRole.id,
        policy: pulumi.interpolate`{
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Action": [
                "s3:GetObject",
                "s3:PutObject",
                "s3:DeleteObject"
              ],
              "Resource": "${this.s3Bucket.arn}/*"
            },
            {
              "Effect": "Allow",
              "Action": [
                "s3:ListBucket",
                "s3:GetBucketVersioning"
              ],
              "Resource": "${this.s3Bucket.arn}"
            }
          ]
        }`,
      },
      componentOpts
    );

    // ============================================================================
    // Security Group for RDS
    // ============================================================================

    this.rdsSecurityGroup = new aws.ec2.SecurityGroup(
      `${resourceName}-rds-sg`,
      {
        description: `Security group for ${resourceName} RDS instance`,
        ingress: [
          {
            protocol: "tcp",
            fromPort: 5432,
            toPort: 5432,
            cidrBlocks: ["10.0.0.0/8"], // Restrict to internal CIDR
          },
        ],
        egress: [
          {
            protocol: "-1",
            fromPort: 0,
            toPort: 0,
            cidrBlocks: ["0.0.0.0/0"],
          },
        ],
        tags: args.tags,
      },
      componentOpts
    );

    // ============================================================================
    // RDS PostgreSQL Instance with Deletion Protection
    // ============================================================================

    this.rdsInstance = new aws.rds.Instance(
      `${resourceName}-postgres`,
      {
        allocatedStorage: args.rdsStorageSize,
        engine: "postgres",
        engineVersion: "15.3", // Specify a stable version
        instanceClass: args.rdsInstanceClass,
        dbName: args.serviceName.replace(/-/g, "_"),
        username: "postgres",
        password: new pulumi.Config().requireSecret("rds_password"),
        multiAz: args.rdsMultiAZ,
        publiclyAccessible: false,
        skipFinalSnapshot: args.environment === "dev",
        finalSnapshotIdentifier: args.environment === "prod"
          ? `${resourceName}-final-snapshot-${Date.now()}`
          : undefined,
        deletionProtection: args.enableDeletionProtection,
        backupRetentionPeriod: args.rdsBackupRetentionDays,
        backupWindow: "03:00-04:00",
        maintenanceWindow: "sun:04:00-sun:05:00",
        storageEncrypted: true,
        vpcSecurityGroupIds: [this.rdsSecurityGroup.id],
        tags: args.tags,
        copyTagsToSnapshot: true,
      },
      componentOpts
    );

    // Register outputs
    this.registerOutputs({
      s3BucketName: this.s3Bucket.id,
      s3BucketArn: this.s3Bucket.arn,
      rdsEndpoint: this.rdsInstance.endpoint,
      rdsDbName: this.rdsInstance.dbName,
      iamRoleArn: this.iamRole.arn,
      rdsSecurityGroupId: this.rdsSecurityGroup.id,
    });
  }
}
```

